// ===== v2: slimmer pane with the half-circle gauge; hover carries a pen's part of the task; click leaves the task =====
const PS = 316;
const paneSlim = (head, body) => paneFit(head, body).replace('width: ' + PW + 'px;', 'width: ' + PS + 'px;');
// the half circle: the parts end to end, the main number inside, the parts as filter rows beside it
const gauge = (parts, total, big, small, on) => {
  const r = 50, cx = 62, cy = 60, L = Math.PI * r; let acc = 0;
  const arcs = parts.map((p) => { const len = (p[2] / total) * L, d = Math.max(0, len - 2.5), s = '<path d="M' + (cx - r) + ' ' + cy + ' A' + r + ' ' + r + ' 0 0 1 ' + (cx + r) + ' ' + cy + '" fill="none" stroke="' + p[0] + '" stroke-width="11" stroke-dasharray="' + d.toFixed(1) + ' ' + L.toFixed(1) + '" stroke-dashoffset="' + (-acc).toFixed(1) + '"></path>'; acc += len; return s; }).join('');
  const svg = '<svg viewBox="0 0 124 70" style="width: 124px; height: 70px; flex: none;"><path d="M' + (cx - r) + ' ' + cy + ' A' + r + ' ' + r + ' 0 0 1 ' + (cx + r) + ' ' + cy + '" fill="none" stroke="#dce0d4" stroke-width="11"></path>' + arcs + '<text x="62" y="52" text-anchor="middle" font-family="Geist, system-ui" font-size="22" font-weight="600" fill="' + K.ink + '">' + big + '</text><text x="62" y="67" text-anchor="middle" font-family="Geist, system-ui" font-size="10.5" fill="' + K.muted + '">' + small + '</text></svg>';
  const rows = parts.map((p) => '<div style="' + st({ display: 'flex', alignItems: 'center', gap: '8px', height: '30px', padding: '0 8px', borderRadius: '8px', background: on === p[1] ? K.press : 'transparent', fontSize: '13px' }) + '"><i style="width: 10px; height: 10px; border-radius: 3px; background: ' + p[0] + '; flex: none;"></i><span style="flex: 1;">' + p[1] + '</span><b style="font-weight: 600;">' + p[2] + '</b></div>').join('');
  return '<div style="display: flex; align-items: center; gap: 8px; padding: 12px 10px 12px 12px; background: #FFFFFF; border: 1px solid ' + K.line + '; border-radius: 16px;">' + svg + '<div style="flex: 1; min-width: 0;">' + rows + '</div></div>';
};
const slimBtns = '<div style="display: flex; gap: 8px; margin-top: 12px;">' + fbtn(ic(SC2.ext, 15) + '&nbsp; Open page') + fbtn(ic(I.log, 16) + '&nbsp; Log') + '</div>';
const rxSlim = () => paneSlim(thead({ title: 'Treatment RX-25G009', sub: 'Amoxicillin · dose 2 of 3 today' }), gauge([[ST.done[0], 'Given', 2], ['#3972B7', 'Due', 1], [ST.look[0], 'Skipped', 1]], 4, '2', 'of 4 sows') + slimBtns);
const vaxSlim = () => paneSlim(thead({ title: 'PRRS vaccine', sub: 'Batch 30 and 31 · 2 rooms', ico: SHIELD, icoBg: K.greenT, icoInk: K.green }), gauge([[ST.done[0], 'Done', 44], [ST.part[0], 'Under way', 2], [ST.look[0], 'Needs a look', 1], [ST.todo[0], 'To do', 57]], 104, '44', 'of 104 pens') + mu('416 of 958 weaners vaccinated', { display: 'block', margin: '8px 4px 0', fontSize: '12.5px' }) +
  sec('Rooms', 'pens left') + box([{ h: t('Nursery 1', { flex: 1, fontWeight: 500 }) + mu('16') + ic(I.chev, 14, 1.8, K.faint) }, { h: t('Nursery 2', { flex: 1, fontWeight: 500 }) + mu('44') + ic(I.chev, 14, 1.8, K.faint) }]) + slimBtns);
const hov = (x, y, w, head, sub, lines, foot) => card({ left: x + 'px', top: y + 'px', width: w + 'px' }, '<div style="padding: 11px 13px;"><div style="display: flex; justify-content: space-between; align-items: baseline; gap: 8px;">' + t(head, { fontWeight: 600 }) + mu(sub, { fontSize: '12px' }) + '</div><div style="height: 1px; background: ' + K.line + '; margin: 8px 0 6px;"></div>' + lines.map((l) => '<div style="display: flex; align-items: flex-start; gap: 8px; padding: 3px 0; font-size: 13px; line-height: 18px;">' + (l[0] ? '<span style="margin-top: 1px;">' + l[0] + '</span>' : '') + '<span style="flex: 1; display: flex; flex-direction: column;"><span style="font-weight: ' + (l[3] ? 600 : 500) + '; color: ' + (l[3] || K.ink) + ';">' + l[1] + '</span>' + (l[2] ? '<span style="font-size: 12px; color: ' + K.muted + ';">' + l[2] + '</span>' : '') + '</span></div>').join('') + '<div style="margin-top: 6px; font-size: 12px; color: ' + K.muted + ';">' + foot + '</div></div>');
const sm = (k) => dose(k).replace(/22px/g, '18px').replace(/14px/g, '12px');
const B12 = ctr('n1', 'B12');

frames.f2 = { bg: 'tx', cap: 'One room: a slimmer pane. The task, the half circle (2 of 4 given), and its parts as filters. The map does the rest: each pen takes one fill.', html: () => tabsStrip('Farm view') + fbar() + rxSlim() + vctl };
frames.f3 = { bg: 'tx', cap: 'Hover a sow: her part of this task, every dose with when and who. That is all the task needs at her level. Click opens her profile page, outside the task.', html: () => tabsStrip('Farm view') + fbar() + rxSlim() + vctl + hov(PW1.D41[0] - 300 + 26, 450, 262, 'D41 · 205901', 'Sow · P4', [[sm('s'), 'Dose 1 skipped', 'Thu 08:40 · could not stand · G.H', K.amber], [sm('t'), 'Dose 2 due today', '08:30 · 15 mL in the neck', K.blue], [sm('w'), 'Dose 3', 'Sat 7 Nov 08:30']], 'Click to open her profile') };
frames.f4 = { bg: 'nv', cap: 'Two rooms: the same slim pane, the half circle counting pens, and Rooms because the task spans more than one.', html: () => tabsV() + fadeAll + penSvg() + nbar() + vaxSlim() + vctl };
frames.f5 = { bg: 'nv', cap: 'Hover a group pen under way: its numbers. Click goes into the pen on the map, where its pigs are.', html: () => tabsV() + fadeAll + penSvg('n1B11') + nbar() + vaxSlim() + vctl + hov(B11[0] + 16, B11[1] + 14, 236, 'Pen B11', 'Nursery 1 · 9 weaners', [['', '6 of 9 vaccinated', '3 to do · last 08:10 G.H']], 'Click to go into the pen') };
frames.f6 = { bg: 'nv', cap: 'Hover a pen that needs a look: why, and who said so. Amber wins over the pen\'s progress.', html: () => tabsV() + fadeAll + penSvg('n1B12') + nbar() + vaxSlim() + vctl + hov(B12[0] + 16, B12[1] + 14, 250, 'Pen B12', 'Nursery 1 · 9 weaners', [['', 'Needs a look', '2 coughing, not vaccinated · 08:20 G.H', K.amber], ['', '7 of 9 vaccinated', '']], 'Click to go into the pen') };
